-- ── story 2-4b: expiry from shelf life ──────────────────────────────────
-- Generated by drizzle-kit (the two column statements) and hand-amended
-- around the generated part: the fail-fast guard, the two CHECKs and the
-- post-migration probe (drizzle-kit is blind to CHECKs; `bun run db:generate`
-- afterwards reports "No schema changes").
--
-- A receipt line of a batch-tracked SKU with a mfg date and no typed expiry
-- now gets its batch expiry set from the SKU's shelf life (mfg +
-- `skus.shelf_life_days`, `grn.submit`'s step 3b). Two columns record it:
--
-- `batches` (large — one row per lot ever received):
--   * `expiry_source text NULL` — `typed` (the label's date, typed on a
--     receipt line) or `derived` (set from mfg + shelf life). Written by a
--     receipt only; every existing row, and every other batch-creating path,
--     stays NULL — read as typed or unknown, and never overwritten. A typed
--     receipt line replaces a `derived` expiry, never a typed or NULL one.
--   * `batches_expiry_source_check` — the vocabulary (`IS NULL OR` first, guide
--     §3), and `batches_expiry_source_dated` — a derived source has a date.
--   Both CHECKs are added NOT VALID (guide §3): a VALID add would scan
--   `batches` under the ADD COLUMN's ACCESS EXCLUSIVE lock, and the migrator
--   applies the whole pending set in ONE transaction. Every existing row
--   carries NULL in the new column, which both CHECKs admit by construction,
--   so the VALIDATE is bookkeeping for a later deploy (PENDING, deploy;
--   DEPLOY.md §5), never a scan under this one's lock.
--
-- `clients` (one row per brand — small):
--   * `derive_expiry boolean NOT NULL DEFAULT true` — the per-client switch
--     (design review A6). A constant default, so the ADD COLUMN is
--     metadata-only; every existing client reads true — a DELIBERATE
--     behaviour change at deploy: a tenant whose SKUs already carry a shelf
--     life starts getting expiries on new batches, and on NULL-expiry
--     batches it receives into again (spec, Design Notes).
--
-- No backfill and no index. Lock cost: each ALTER TABLE takes a brief ACCESS
-- EXCLUSIVE lock (no rewrite, no scan); the deploy migrator's lock_timeout
-- applies (DEPLOY.md §5).

-- ── 0. fail-fast: already applied ────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.columns
		 WHERE table_schema = 'public' AND table_name = 'batches' AND column_name = 'expiry_source'
	) THEN
		RAISE EXCEPTION 'migration 0108: batches.expiry_source already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
ALTER TABLE "batches" ADD COLUMN "expiry_source" text;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "derive_expiry" boolean DEFAULT true NOT NULL;--> statement-breakpoint
-- ── hand-amended: the CHECKs (migration SQL only) ────────────────────────
-- Mirrored by BATCH_EXPIRY_SOURCES (src/modules/catalog/catalog.facade.ts),
-- pinned against these definitions by test/receipt-expiry-derivation.spec.ts.
ALTER TABLE "batches" ADD CONSTRAINT "batches_expiry_source_check" CHECK (
	"expiry_source" IS NULL OR "expiry_source" IN ('typed','derived')
) NOT VALID;--> statement-breakpoint
ALTER TABLE "batches" ADD CONSTRAINT "batches_expiry_source_dated" CHECK (
	"expiry_source" IS DISTINCT FROM 'derived' OR "expiry_date" IS NOT NULL
) NOT VALID;--> statement-breakpoint
-- ── the post-migration assertion (the 0094 / 0106 model) ──────────────────
-- Made-up uuids. (a) Both batches CHECKs are present and NOT VALID. (b) Every
-- existing client derives (no batches scan). (c)
-- The accepted shapes are inserted and rolled back by a sentinel exception,
-- so a CHECK that refused everything fails the migration. (d) Each refused
-- shape runs in its own subtransaction and must be refused BY ITS NAMED
-- CONSTRAINT (each probe row violates only its target: an active batch with
-- no block fields satisfies `batches_blocked_pairing` and `batches_status_check`;
-- `batches_expiry_source_check` sorts before `batches_expiry_source_dated`, so
-- the dated probe uses a valid source).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	s uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
	n bigint;
BEGIN
	-- (a)
	SELECT count(*) INTO n
	  FROM pg_constraint
	 WHERE conrelid = 'public.batches'::regclass
	   AND conname IN ('batches_expiry_source_check', 'batches_expiry_source_dated')
	   AND contype = 'c'
	   AND NOT convalidated;
	IF n <> 2 THEN
		RAISE EXCEPTION 'migration 0108: expected the two batches CHECKs present and NOT VALID, found % so.', n;
	END IF;
	-- (b) no batches scan here: `expiry_source` is NULL on every existing row
	-- by construction, and a scan under the ADD COLUMN's lock is the cost the
	-- NOT VALID CHECKs avoid. `clients` is small.
	SELECT count(*) INTO n FROM "clients" WHERE NOT "derive_expiry";
	IF n <> 0 THEN
		RAISE EXCEPTION 'migration 0108: % existing client(s) do not read derive_expiry = true.', n;
	END IF;
	-- (c) accepted: NULL source with and without a date, typed with a date,
	-- typed without one (a typed fill always has one, but the CHECK does not
	-- demand it), derived with a date; a client inserted without the switch
	-- reads true, one with it off is admitted.
	BEGIN
		INSERT INTO "batches" ("id","tenant_id","sku_id","code","expiry_date","expiry_source")
		VALUES
			(gen_random_uuid(), t, s, 'P-NULL', NULL, NULL),
			(gen_random_uuid(), t, s, 'P-NULL-DATED', '2027-02-27T18:30:00Z', NULL),
			(gen_random_uuid(), t, s, 'P-TYPED', '2027-02-27T18:30:00Z', 'typed'),
			(gen_random_uuid(), t, s, 'P-TYPED-UNDATED', NULL, 'typed'),
			(gen_random_uuid(), t, s, 'P-DERIVED', '2027-02-27T18:30:00Z', 'derived');
		INSERT INTO "clients" ("id","tenant_id","code","name") VALUES (c, t, 'PROBE-0108', 'probe');
		IF (SELECT "derive_expiry" FROM "clients" WHERE "id" = c) IS DISTINCT FROM true THEN
			RAISE EXCEPTION 'migration 0108: a client inserted without the switch did not read derive_expiry = true.';
		END IF;
		INSERT INTO "clients" ("id","tenant_id","code","name","derive_expiry") VALUES (gen_random_uuid(), t, 'PROBE-0108-OFF', 'probe', false);
		RAISE EXCEPTION USING ERRCODE = 'P0108', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR not_null_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0108: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0108' THEN
			NULL;
	END;
	-- (d) refused shapes.
	FOREACH probe IN ARRAY ARRAY['unknown source', 'empty source', 'derived without a date', 'client switch null'] LOOP
		refused_by := NULL;
		expected := CASE
			WHEN probe IN ('unknown source', 'empty source') THEN 'batches_expiry_source_check'
			WHEN probe = 'derived without a date' THEN 'batches_expiry_source_dated'
			ELSE 'not-null'
		END;
		BEGIN
			CASE probe
				WHEN 'unknown source' THEN
					INSERT INTO "batches" ("id","tenant_id","sku_id","code","expiry_date","expiry_source")
					VALUES (gen_random_uuid(), t, s, 'P-BAD', '2027-02-27T18:30:00Z', 'guessed');
				WHEN 'empty source' THEN
					INSERT INTO "batches" ("id","tenant_id","sku_id","code","expiry_date","expiry_source")
					VALUES (gen_random_uuid(), t, s, 'P-BAD', '2027-02-27T18:30:00Z', '');
				WHEN 'derived without a date' THEN
					INSERT INTO "batches" ("id","tenant_id","sku_id","code","expiry_date","expiry_source")
					VALUES (gen_random_uuid(), t, s, 'P-BAD', NULL, 'derived');
				WHEN 'client switch null' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","derive_expiry") VALUES (gen_random_uuid(), t, 'PROBE-0108-NULL', 'probe', NULL);
			END CASE;
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN not_null_violation THEN
				refused_by := 'not-null';
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0108: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "batches" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "clients" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0108: a probe row survived.';
	END IF;
END $$;
